# EVOLVE-BLOCK-START
import networkx as nx
import json
import os
import pandas as pd
from typing import Dict, List


def search_algorithm(src, dsts, G, num_partitions):
    """Compute a minimum-cost shared directed multicast tree when feasible.

    A Dreyfus-Wagner subset dynamic program finds the least-cost union of
    directed links from ``src`` to up to twelve unique remote destinations.
    Thus shared inter-cloud links are paid for once before data branches.
    Larger requests use marginal-cost attachment as a bounded-time fallback.
    """
    import heapq

    topology = BroadCastTopology(src, dsts, num_partitions)
    terminals = list(dict.fromkeys(dst for dst in dsts if dst != src))

    if not terminals:
        for dst in dsts:
            for partition in range(num_partitions):
                topology.set_dst_partition_paths(dst, partition, [])
        return topology

    h = nx.DiGraph()
    for u, v, data in G.edges(data=True):
        try:
            cost = float(data.get("cost"))
        except (TypeError, ValueError):
            continue
        if u != v and v != src and cost >= 0:
            h.add_edge(u, v, cost=cost)

    if src not in h or any(dst not in h for dst in terminals):
        return topology

    def install(edges):
        tree = nx.DiGraph()
        tree.add_edges_from(edges)
        for dst in dsts:
            if dst == src:
                path = []
            else:
                try:
                    nodes = nx.shortest_path(tree, src, dst)
                    path = [[u, v, G[u][v]]
                            for u, v in zip(nodes, nodes[1:])]
                except (nx.NetworkXNoPath, nx.NodeNotFound):
                    continue
            for partition in range(num_partitions):
                topology.set_dst_partition_paths(dst, partition, path)

    if len(terminals) <= 12:
        nodes = list(h.nodes)
        pos = {node: i for i, node in enumerate(nodes)}
        reverse = {node: [] for node in nodes}
        for u, v, data in h.edges(data=True):
            reverse[v].append((u, data["cost"]))

        count = 1 << len(terminals)
        inf = float("inf")
        dp = [[inf] * len(nodes) for _ in range(count)]
        choice = [[None] * len(nodes) for _ in range(count)]

        for bit, dst in enumerate(terminals):
            dp[1 << bit][pos[dst]] = 0.0
            choice[1 << bit][pos[dst]] = ("terminal",)

        for mask in range(1, count):
            sub = (mask - 1) & mask
            while sub:
                other = mask ^ sub
                if sub < other:
                    for i in range(len(nodes)):
                        value = dp[sub][i] + dp[other][i]
                        if value < dp[mask][i]:
                            dp[mask][i] = value
                            choice[mask][i] = ("split", sub, other)
                sub = (sub - 1) & mask

            queue = [(dp[mask][i], i) for i in range(len(nodes))
                     if dp[mask][i] < inf]
            heapq.heapify(queue)
            while queue:
                value, vi = heapq.heappop(queue)
                if value != dp[mask][vi]:
                    continue
                v = nodes[vi]
                for u, cost in reverse[v]:
                    ui = pos[u]
                    candidate = value + cost
                    if candidate < dp[mask][ui]:
                        dp[mask][ui] = candidate
                        choice[mask][ui] = ("edge", v)
                        heapq.heappush(queue, (candidate, ui))

        full = count - 1
        if dp[full][pos[src]] < inf:
            edges = set()

            def recover(mask, node):
                action = choice[mask][pos[node]]
                if action is None or action[0] == "terminal":
                    return
                if action[0] == "split":
                    recover(action[1], node)
                    recover(action[2], node)
                else:
                    edges.add((node, action[1]))
                    recover(mask, action[1])

            recover(full, src)
            install(edges)
            return topology

    selected = set()
    remaining = set(terminals)
    while remaining:
        def marginal(u, v, data):
            return 0.0 if (u, v) in selected else data["cost"]

        distances, paths = nx.single_source_dijkstra(h, src, weight=marginal)
        reachable = [dst for dst in remaining if dst in distances]
        if not reachable:
            break
        dst = min(reachable, key=distances.get)
        path = paths[dst]
        selected.update(zip(path, path[1:]))
        remaining.remove(dst)

    install(selected)
    return topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        """
        Append path for partition = partition to reach dst
        """
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    """
    Default graph with capacity constraints and cost info
    nodes: regions, edges: links
    per edge:
        throughput: max tput achievable (gbps)
        cost: $/GB
        flow: actual flow (gbps), must be < throughput, default = 0
    """
    # Use relative path from this file's location
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(os.path.join(current_dir, "profiles/throughput.csv"))
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(row["src_region"], row["dst_region"], cost=None, throughput=num_vms * row["throughput_sent"] / 1e9)

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    # some pairs not in the cost grid
    no_cost_pairs = []
    for edge in G.edges.data():
        src, dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((src, dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G


